'use strict';
const M=SlateAdminModel, $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>JSON.parse(JSON.stringify(x));
let db;try{db=M.load();M.save(db);}catch(e){db=M.seed();}
let signedIn=false;try{signedIn=sessionStorage.getItem('otp-slate-admin-session')==='active';}catch(_){}
const state={view:'overview',org:'all',role:'Platform admin',query:'',status:'all',page:0,selected:new Set(),profile:null,accessTab:'profiles',import:null};
let lastFocus=null,toastTimer=null;
const icons={overview:'<path d="M4 16a8 8 0 1 1 16 0M12 16l4-5"/>',organizations:'<path d="M4 21V4h10v17M14 9h6v12M8 8h2M8 12h2M8 16h2M17 13h1M17 17h1"/>',students:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6M18 13a5 5 0 0 1 3 4v4"/>',access:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4M12 14v3"/>',imports:'<path d="M4 14v7h16v-7M12 16V3M7 8l5-5 5 5"/>',exams:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 3h6v4H9M8 12h8M8 16h5"/>',jobs:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',team:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-4a7 7 0 0 1 14 0v4M3 4l1 2M21 4l-1 2"/>',reports:'<path d="M4 3v18h17M8 17v-5M13 17V8M18 17V5"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',logout:'<path d="M10 4H4v16h6M10 12h11M17 8l4 4-4 4"/>'};
const svg=id=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[id]}</svg>`;
const can=()=>true;
const allowedOrgs=()=>db.orgs;
const orgs=()=>allowedOrgs().filter(o=>state.org==='all'||o.id===state.org);
const inScope=o=>allowedOrgs().some(x=>x.id===o)&&(state.org==='all'||state.org===o);
const students=()=>db.students.filter(s=>inScope(s.org));
const currentOrg=()=>allowedOrgs().find(o=>o.id===state.org);
const orgName=id=>db.orgs.find(o=>o.id===id)?.name||'Organization';
const profileName=s=>s.custom?'Individual access':db.profiles.find(p=>p.id===s.profile&&p.org===s.org)?.name||'No access assigned';
const date=s=>new Date(s).toLocaleString('en-IN',{day:'numeric',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Kolkata'});
const badge=s=>`<span class="pill ${['Active','Published','Live'].includes(s)?'green':['Suspended','Archived','Withdrawn'].includes(s)?'red':'amber'}">${esc(s)}</span>`;
const disabled=cap=>can(cap)?'':' disabled';
function guard(cap,org){if(org&&!db.orgs.some(o=>o.id===org))throw new Error('Organization not found.');}
function requireOrg(cap){guard(cap);const o=currentOrg();if(!o)throw new Error('Select an organization first.');if(o.status!=='Active')throw new Error('Restore this organization before adding or changing access.');return o;}
function commit(action,detail,org=null){M.audit(db,'Platform admin',org,action,detail);try{M.save(db);}catch(e){try{db=M.load();}catch(_){}throw new Error('Device storage is full or unavailable. This change could not be saved.');}}
function toast(message){clearTimeout(toastTimer);const t=$('#toast');t.className='toast';t.hidden=false;t.textContent=message;toastTimer=setTimeout(()=>t.hidden=true,4500);}
function nav(view){state.view=view;state.query='';state.status='all';state.page=0;state.selected.clear();state.import=null;closeModal();render();$('.workspace').scrollTop=0;}
function head(title,description,buttons=''){return `<div class="page-head"><div><h1>${title}</h1><p>${description}</p></div><div class="actions">${buttons}</div></div>`;}
function stat(label,value,note){return `<div class="stat"><small>${label}</small><b>${value}</b><span>${note}</span></div>`;}
function empty(title,text,action=''){return `<div class="empty"><div class="empty-icon" aria-hidden="true">◎</div><h2>${title}</h2><p>${text}</p>${action}</div>`;}
function login(){return `<div class="login"><section class="login-art"><div class="logo-mark">OTP</div><div><p class="eyebrow" style="color:#a0b8d6">OTP SLATE · PLATFORM ADMIN</p><h1>Shape every learning journey.</h1><p>Create organizations, bring students on board and give each learner the right access.</p></div><small style="color:#a0b8d6">The management portal for your platform.</small></section><section class="login-form"><p class="eyebrow">PLATFORM ADMIN</p><h2>Welcome to your workspace.</h2><p class="muted">Manage organizations, enrollment and viewer accounts.</p><div class="note">Local UI prototype. Changes save on this device. Platform authentication and server permissions will be connected later.</div><button class="btn pri button-full" data-action="login">Enter platform preview →</button><p style="margin-top:24px"><a href="otp-slate-organization-admin.html">Organization Admin sign in →</a></p></section></div>`;}
function render(){
 if(!signedIn){$('#root').innerHTML=login();return;}
 const allowed=allowedOrgs();
 const pages={overview:vOverview,organizations:vOrganizations,students:vStudents,access:vAccess,imports:vImports,exams:vExams,jobs:vJobs,team:vTeam,reports:vReports,activity:vActivity,settings:vSettings};
 const navs=[['overview','Overview'],['organizations','Organizations'],['students','Students'],['access','Access'],['imports','Import'],['exams','Live Exams'],['jobs','Jobs'],['team','Members'],['reports','Reports'],['activity','Activity'],['settings','Settings']];
 $('#root').innerHTML=`<div class="shell"><nav class="rail" aria-label="Platform admin navigation"><div class="logo"><div class="logo-mark" aria-label="OTP Slate">OTP</div></div>${navs.map(([id,n])=>`<button class="nav-btn${state.view===id?' active':''}" data-action="nav" data-view="${id}" aria-current="${state.view===id?'page':'false'}">${svg(id)}${n}</button>`).join('')}<div class="rail-spacer"></div><button class="nav-btn" data-action="logout">${svg('logout')}Log out</button></nav><div class="workspace"><header class="topbar"><div class="top-brand">OTP Slate <small>Platform Admin</small></div><select class="org-select" id="orgSelect" aria-label="Organization scope"><option value="all">All organizations</option>${allowed.map(o=>`<option value="${o.id}" ${state.org===o.id?'selected':''}>${esc(o.name)}</option>`).join('')}</select><div class="top-right"><span class="pill">Local preview</span><span class="muted">Platform Admin</span><span class="avatar" title="Admin preview">MJ</span></div></header><div class="scope-message">${state.org==='all'?'Viewing all organizations':'Organization: '+esc(orgName(state.org))} · Enrollment and access are managed here.</div><main class="page" id="main">${pages[state.view]()}</main></div></div>`;
}
function vOverview(){
 const all=students(),active=all.filter(s=>s.status==='Active'),withAccess=all.filter(s=>Object.keys(M.effective(db,s).courses).length||M.effective(db,s).practices.length);
 return head('Overview','A clear view of your organizations and learners.',`<button class="btn" data-action="nav" data-view="imports"${disabled('students')}>Import students</button><button class="btn pri" data-action="new-org"${disabled('orgs')}>+ Create organization</button>`)+`<section class="hero"><div><p class="eyebrow">EVERY LEARNER, THE RIGHT ACCESS</p><h2>Build the pathway. Open the doors.</h2><p>Organize students into cohorts and assign only the courses, modules and practice activities they need.</p></div><span class="hero-symbol" aria-hidden="true">◎</span></section><div class="stats">${stat('Organizations',orgs().length,'Independent student rosters')}${stat('Students',all.length,active.length+' active accounts')}${stat('Learning access assigned',withAccess.length,'Students with effective access')}${stat('Needs assignment',all.length-withAccess.length,'No learning resources assigned')}</div><div class="split"><section class="panel"><div class="panel-head"><h2>Your organizations</h2><button class="btn link" data-action="nav" data-view="organizations">View all →</button></div><div class="table-wrap"><table><thead><tr><th>Organization</th><th>Students</th><th>Status</th><th></th></tr></thead><tbody>${orgs().map(o=>`<tr><td><strong>${esc(o.name)}</strong><small>${esc(o.code)} · ${esc(o.city)}</small></td><td>${db.students.filter(s=>s.org===o.id).length}</td><td>${badge(o.status)}</td><td><button class="btn" data-action="open-org" data-id="${o.id}">Manage</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Recent activity</h2></div>${auditRows(db.audit.filter(a=>!a.org||inScope(a.org)).slice(0,4))}<div class="panel-body"><button class="btn link" data-action="nav" data-view="activity">Open activity log →</button></div></section></div><section class="grid"><article class="card"><h2>Bring your students on board</h2><p>Download the Excel template, validate your list and create students in one import.</p><button class="btn" data-action="nav" data-view="imports">Open import</button></article><article class="card"><h2>Make access repeatable</h2><p>Create a profile for a cohort, then refine individual module access when needed.</p><button class="btn" data-action="nav" data-view="access">Manage access</button></article><article class="card"><h2>Release the next assessment</h2><p>Create a draft and publish a live exam to the students in its audience.</p><button class="btn" data-action="nav" data-view="exams">Manage exams</button></article></section>`;
}
function vOrganizations(){
 return head('Organizations','Separate spaces for every institution, academy and training team.',`<button class="btn pri" data-action="new-org"${disabled('orgs')}>+ Create organization</button>`)+`<div class="grid">${orgs().map(o=>`<article class="card"><div class="card-top"><div class="org-icon">${esc(o.code.slice(0,3))}</div>${badge(o.status)}</div><h2>${esc(o.name)}</h2><p>${esc(o.type)} · ${esc(o.city)}<br>${esc(o.contact)}</p><div class="stat-foot"><span>${db.students.filter(s=>s.org===o.id).length} students</span><span>${db.profiles.filter(p=>p.org===o.id).length} access profiles</span></div><div class="actions"><button class="btn pri" data-action="open-org" data-id="${o.id}">Manage organization</button><button class="btn" data-action="edit-org" data-id="${o.id}"${disabled('orgs')}>Edit</button><button class="btn" data-action="org-status" data-id="${o.id}"${disabled('orgs')}>${o.status==='Active'?'Archive':'Restore'}</button></div></article>`).join('')}</div>${orgs().length?'':empty('No organizations yet','Create an organization before adding students or assigning access.')}`;
}
function studentRows(list){return list.map(s=>`<tr><td><input type="checkbox" data-select="${s.id}" aria-label="Select ${esc(s.name)}" ${state.selected.has(s.id)?'checked':''}${disabled('students')}></td><td><strong>${esc(s.name)}</strong><small>${esc(s.student_id)} · ${esc(s.email)}</small></td>${state.org==='all'?`<td>${esc(db.orgs.find(o=>o.id===s.org)?.code)}</td>`:''}<td>${esc(s.cohort)||'—'}</td><td>${badge(s.status)}</td><td>${esc(profileName(s))}<small>${s.accessUntil?'Until '+esc(s.accessUntil):'No expiry'}</small></td><td class="table-action"><button class="btn" data-action="student-view" data-id="${s.id}">View access</button> <button class="btn" data-action="edit-student" data-id="${s.id}"${disabled('students')}>Edit</button></td></tr>`).join('');}
function filteredStudents(){const q=state.query.toLowerCase();return students().filter(s=>(state.status==='all'||s.status===state.status)&&`${s.name} ${s.email} ${s.student_id} ${s.cohort}`.toLowerCase().includes(q));}
function studentTable(){const list=filteredStudents(),size=20;state.page=Math.min(state.page,Math.max(0,Math.ceil(list.length/size)-1));return `<div class="panel"><div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="selectPage" aria-label="Select this page"${disabled('students')}></th><th>Student</th>${state.org==='all'?'<th>Organization</th>':''}<th>Cohort</th><th>Status</th><th>Access</th><th>Actions</th></tr></thead><tbody>${studentRows(list.slice(state.page*size,(state.page+1)*size))}</tbody></table>${list.length?'':empty('No students found','Adjust your filters or add students to this organization.')}</div><div class="pagination"><span>${list.length} students · Page ${state.page+1} of ${Math.max(1,Math.ceil(list.length/size))}</span><div class="actions"><button class="btn" data-action="page" data-dir="-1" ${state.page===0?'disabled':''}>Previous</button><button class="btn" data-action="page" data-dir="1" ${(state.page+1)*size>=list.length?'disabled':''}>Next</button></div></div></div>`;}
function vStudents(){return head('Students','Create learners and control their organization membership.',`<button class="btn" data-action="export-students">Export CSV</button><button class="btn" data-action="nav" data-view="imports"${disabled('students')}>Import students</button><button class="btn pri" data-action="new-student"${disabled('students')}>+ Add student</button>`)+`<div class="toolbar"><input class="search" id="studentSearch" type="search" aria-label="Search students" placeholder="Search name, ID, email or cohort" value="${esc(state.query)}"><select id="studentStatus" aria-label="Student status">${['all','Active','Suspended'].map(v=>`<option value="${v}" ${state.status===v?'selected':''}>${v==='all'?'All statuses':v}</option>`).join('')}</select><span id="selectedCount" class="muted">${state.selected.size} selected</span><button class="btn" data-action="bulk-profile"${disabled('access')}>Assign access</button><button class="btn" data-action="bulk-status" data-status="Suspended"${disabled('students')}>Suspend</button><button class="btn" data-action="bulk-status" data-status="Active"${disabled('students')}>Activate</button></div><div id="studentTable">${studentTable()}</div>`;}
function grantEditor(grants=M.emptyGrants()){
 const labels={tracks:'Courses',dsa:'Advanced DSA',fullstack:'Full Stack',hiring:'Hiring Assessments',crt:'CRT Modules',cc:'Competitive Coding',pyq:'Company PYQs'};
 return `<div class="note">Start with no access. Select a course to grant every module, or expand it and choose specific modules. Unselected resources remain unavailable to students.</div>${Object.entries(labels).map(([cat,name])=>`<h3 class="subheading">${name}</h3>${M.catalog.filter(c=>c.cat===cat).map(c=>{const selected=grants.courses[c.id];return `<details class="resource"><summary>${esc(c.name)} <span class="grant-count">· ${c.mods.length} modules</span></summary><div class="resource-body"><div class="checks"><label><input type="checkbox" data-course-all="${c.id}" ${selected==='all'?'checked':''}>All modules</label></div><div class="module-grid">${c.mods.map((m,i)=>`<label><input type="checkbox" data-module="${c.id}" data-index="${i}" ${selected==='all'||selected?.includes(i)?'checked':''}>${i+1}. ${esc(m)}</label>`).join('')}</div></div></details>`}).join('')}`).join('')}<h3 class="subheading">Practice activities</h3><div class="module-grid">${PRACTICES.map(([id,name])=>`<label><input type="checkbox" data-practice="${id}" ${grants.practices.includes(id)?'checked':''}>${name}</label>`).join('')}</div><h3 class="subheading">Career and dashboard tools</h3><div class="checks">${[['jobs','Jobs'],['resume','Resume Builder'],['rankings','Student rankings']].map(([id,name])=>`<label><input type="checkbox" data-feature="${id}" ${grants.features.includes(id)?'checked':''}>${name}</label>`).join('')}</div>`;
}
const PRACTICES=[['aptitude','Aptitude practice'],['live','Timed aptitude mock'],['quant','Competitive aptitude'],['logic','Logical reasoning'],['typing','Typing speed test'],['practice','Programming practice'],['livecode','Timed coding mock'],['cp','Competitive programming'],['sql-practice','SQL practice'],['webdev','Web development'],['interview','Interview practice']];
function readGrants(root){const g=M.emptyGrants();for(const c of M.catalog){if($(`[data-course-all="${c.id}"]`,root)?.checked)g.courses[c.id]='all';else{const modules=$$(`[data-module="${c.id}"]:checked`,root).map(i=>+i.dataset.index);if(modules.length)g.courses[c.id]=modules;}}g.practices=$$('[data-practice]:checked',root).map(x=>x.dataset.practice);g.features=$$('[data-feature]:checked',root).map(x=>x.dataset.feature);return g;}
function grantSummary(g){return `${Object.keys(g.courses).length} courses · ${g.practices.length} practices · ${g.features.length} tools`;}
function vAccess(){
 const profiles=db.profiles.filter(p=>inScope(p.org));if(!profiles.some(p=>p.id===state.profile))state.profile=profiles[0]?.id;
 const p=profiles.find(p=>p.id===state.profile);
 return head('Learning access','Admin-managed enrollment, down to the individual module.',`<button class="btn" data-action="assign-cohort"${disabled('access')}>Assign to a cohort</button><button class="btn pri" data-action="new-profile"${disabled('access')}>+ Create access profile</button>`)+`<div class="access-layout"><div class="access-list">${profiles.map(p=>`<button class="list-btn ${p.id===state.profile?'active':''}" data-action="profile-select" data-id="${p.id}"><b>${esc(p.name)}</b><small>${esc(orgName(p.org))}</small><small>${db.students.filter(s=>s.org===p.org&&s.profile===p.id&&!s.custom).length} assigned students</small></button>`).join('')}${profiles.length?'':'<p class="muted">No profiles yet.</p>'}</div><section class="panel">${p?`<div class="panel-head"><div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.description)}<br>${grantSummary(p.grants)}</p></div><button class="btn" data-action="edit-profile" data-id="${p.id}"${disabled('access')}>Edit profile</button></div><div class="panel-body"><h3 class="subheading">Assigned learning resources</h3>${grantList(p.grants)}<div class="note">Changes to this profile apply to students using it. Individual access overrides use their own assignments.</div><button class="btn" data-action="profile-students" data-id="${p.id}">Review assigned students →</button></div>`:empty('Create your first access profile','Save a reusable selection of courses, modules and practice activities for your organization.')}</section></div>`;
}
function grantList(g){return `${Object.entries(g.courses).map(([id,mods])=>{const c=M.catalog.find(c=>c.id===id);return `<details class="resource"><summary>${esc(c?.name||id)} <span class="grant-count">· ${mods==='all'?'All modules':mods.length+' selected modules'}</span></summary><div class="resource-body"><p class="muted">${(mods==='all'?c?.mods||[]:mods.map(i=>c?.mods[i])).map(esc).join('<br>')}</p></div></details>`}).join('')}${!Object.keys(g.courses).length?'<p class="muted">No courses assigned.</p>':''}<h3 class="subheading">Practice</h3><p class="muted">${g.practices.map(id=>esc(PRACTICES.find(p=>p[0]===id)?.[1]||id)).join(' · ')||'No practices assigned.'}</p><h3 class="subheading">Tools</h3><p class="muted">${g.features.map(esc).join(' · ')||'No additional tools assigned.'}</p>`;}
function vImports(){
 const info=state.import;const good=info?.rows.filter(r=>!r.errors.length)||[],bad=info?.rows.filter(r=>r.errors.length)||[];
 return head('Import students','Create your roster from a templated Excel file.',`<button class="btn" data-action="template">Download Excel template ↓</button>`)+`<div class="step-list"><span class="step ${!info?'active':''}"><b>1</b>Choose organization & file</span><span class="step ${info?'active':''}"><b>2</b>Validate & review</span><span class="step"><b>3</b>Create students</span></div><div class="split"><section class="panel"><div class="panel-head"><h2>${info?'Review your import':'Upload your roster'}</h2></div><div class="panel-body"><p class="muted">Target: <b>${currentOrg()?esc(currentOrg().name):'Select an organization in the header'}</b></p>${!info?`<div class="dropzone"><label for="importFile">Choose your student list</label><p class="muted">Excel .xlsx or CSV · Maximum file size 10 MB</p><input id="importFile" type="file" accept=".xlsx,.csv" ${can('students')&&currentOrg()?.status==='Active'?'':'disabled'}></div><div class="note">Use the Students sheet and keep its headers unchanged. Student ID, name, email and phone must be unique. Staff roles are managed separately.</div><button class="btn" data-action="demo-import"${disabled('students')}>Try a sample import</button>`:`<p><b>${esc(info.name)}</b></p><div class="checks"><span class="pill green">${good.length} valid rows</span><span class="pill ${bad.length?'red':'green'}">${bad.length} rows with errors</span></div><div class="table-wrap" style="margin-top:18px;max-height:420px"><table><thead><tr><th>Row</th><th>Student</th><th>Access profile</th><th>Validation</th></tr></thead><tbody>${info.rows.slice(0,100).map(r=>`<tr><td>${r.row}</td><td><strong>${esc(r.data.name)}</strong><small>${esc(r.data.email)}</small></td><td>${esc(profileName(r.data))}</td><td>${r.errors.length?`<span class="error">${r.errors.map(esc).join('<br>')}</span>`:'<span class="pill green">Ready</span>'}</td></tr>`).join('')}</tbody></table></div>${info.rows.length>100?'<p class="muted">Showing the first 100 rows. Validation covers the entire file.</p>':''}<div class="note">${bad.length?'Correct the errors in your file and upload again. No students have been created.':'All rows are valid. Confirm below to create these students with the shown access. No invitations or messages are sent in this preview.'}</div><div class="actions"><button class="btn" data-action="cancel-import">Choose another file</button><button class="btn pri" data-action="commit-import" ${bad.length||!good.length||!can('students')?'disabled':''}>Create ${good.length} students</button><button class="btn" data-action="export-import-errors" ${bad.length?'':'disabled'}>Download errors</button></div>`}</div></section><aside class="panel"><div class="panel-head"><h2>A predictable import</h2></div><div class="panel-body"><h3 class="subheading">Required columns</h3><p class="muted">student_id, full_name, email, phone, role, status</p><h3 class="subheading">Optional columns</h3><p class="muted">cohort, access_profile</p><h3 class="subheading">No automatic enrollment</h3><p class="muted">Use “None” to create accounts without learning access. Assign a profile or specific modules afterward.</p><h3 class="subheading">Existing students</h3><p class="muted">This import creates new students only. Duplicates are rejected so access is never silently overwritten.</p></div></aside></div>`;
}
function examAudience(exam){return db.students.filter(s=>s.org===exam.org&&s.status==='Active'&&(!exam.cohort||s.cohort===exam.cohort));}
function vExams(){const exams=db.exams.filter(e=>inScope(e.org));return head('Live Exams','Draft, publish and withdraw exams for selected student audiences.',`<button class="btn pri" data-action="new-exam"${disabled('exams')}>+ Create exam</button>`)+`<div class="grid">${exams.map(e=>`<article class="card"><div class="card-top">${badge(e.status)}<span class="pill">${e.kind==='coding'?'Coding':'Aptitude'}</span></div><h2>${esc(e.title)}</h2><p>${esc(orgName(e.org))}<br>${e.cohort?esc(e.cohort):'All active students'} · ${examAudience(e).length} students</p><div class="stat-foot"><span>${e.duration} minutes</span><span>${e.kind==='coding'?'1 sample problem':'5 sample questions'}</span></div><p class="muted">${e.deadline?'Closes '+date(e.deadline):'No closing date'}</p><div class="actions"><button class="btn" data-action="edit-exam" data-id="${e.id}" ${e.status==='Published'?'disabled':disabled('exams')}>Edit</button><button class="btn pri" data-action="exam-publish" data-id="${e.id}"${disabled('exams')}>${e.status==='Published'?'Withdraw':'Publish now'}</button><button class="btn" data-action="exam-audience" data-id="${e.id}">Audience</button></div></article>`).join('')}</div>${exams.length?'':empty('No exams have been created','Create an exam draft, review its audience, then publish it when students should have access.',`<button class="btn pri" data-action="new-exam"${disabled('exams')}>Create the first exam</button>`)}<div class="note">This prototype publishes availability to the linked student preview. Automated grading, hosted compiler execution and durable exam results need the production backend.</div>`;}
function vJobs(){const jobs=db.jobs.filter(j=>inScope(j.org));return head('Jobs','Share dated job postings that lead directly to the employer’s application page.',`<button class="btn pri" data-action="new-job"${disabled('jobs')}>+ Add job posting</button>`)+`<div class="grid">${jobs.map(j=>`<article class="card"><div class="card-top">${badge(j.status)}<span class="muted">${esc(j.posted)}</span></div><h2>${esc(j.title)}</h2><b>${esc(j.company)}</b><p>${esc(j.description)}</p><small class="muted">${esc(j.location)} · ${esc(orgName(j.org))}</small><div class="actions"><a class="btn" href="${esc(j.url)}" target="_blank" rel="noopener noreferrer">Open posting ↗</a><button class="btn" data-action="edit-job" data-id="${j.id}"${disabled('jobs')}>Edit</button><button class="btn pri" data-action="job-publish" data-id="${j.id}"${disabled('jobs')}>${j.status==='Published'?'Unpublish':'Publish'}</button></div></article>`).join('')}</div>${jobs.length?'':empty('Share your first opportunity','Add a title, description, posting date and application link. Publish it for this organization’s eligible students.')}`;}
function vTeam(){const members=db.members.filter(s=>inScope(s.org));return head('Organization members','Create individual logins for the separate, read-only analytics portal.',`<a class="btn" href="otp-slate-organization-admin.html" target="_blank" rel="noopener">Open analytics portal ↗</a><button class="btn pri" data-action="new-staff">+ Create member account</button>`)+`<div class="note">Each organization can have any number of member email IDs. Every account sees only its assigned organization’s analytics. Members cannot create organizations, edit students, change access or publish content.</div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Member</th><th>Organization</th><th>Access</th><th>Status</th><th>Account</th></tr></thead><tbody>${members.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.email)}</small></td><td>${esc(orgName(s.org))}</td><td>View analytics only</td><td>${badge(s.status)}</td><td><button class="btn" data-action="edit-staff" data-id="${s.id}">Edit / reset password</button> <button class="btn" data-action="member-status" data-id="${s.id}">${s.status==='Active'?'Disable':'Activate'}</button></td></tr>`).join('')}</tbody></table>${members.length?'':empty('No member accounts yet','Select an organization and create a viewer account with an email and password.')}</div></section><section class="panel"><div class="panel-head"><h2>Two separate portals</h2></div><div class="panel-body"><div class="split"><div><h3 class="subheading">Platform Admin</h3><p class="muted">Organization setup, student data, Excel imports, learning access, exams, jobs and member account provisioning.</p></div><div><h3 class="subheading">Organization Admin</h3><p class="muted">Performance trends, course progress, practice results, exam analytics and individual student views. The organization is determined by the member’s login.</p></div></div></div></section>`;}
function vReports(){const list=students();return head('Reports','Live counts from the roster and learning assignments.',`<button class="btn" data-action="export-students">Export student access report</button>`)+`<div class="stats">${stat('Active learners',list.filter(s=>s.status==='Active').length,'Account status')}${stat('Suspended learners',list.filter(s=>s.status==='Suspended').length,'Account access disabled')}${stat('Access profiles',db.profiles.filter(p=>inScope(p.org)).length,'Reusable learning assignments')}${stat('Published exams',db.exams.filter(e=>inScope(e.org)&&e.status==='Published').length,'Released by administrators')}</div><div class="panel"><div class="panel-head"><h2>Course enrollment coverage</h2></div><div class="panel-body">${M.catalog.map(c=>{const n=list.filter(s=>Object.hasOwn(M.effective(db,s).courses,c.id)).length;return n?`<div class="metric-bar"><span>${esc(c.name)}</span><i><b style="width:${list.length?n/list.length*100:0}%"></b></i><b>${n}</b></div>`:''}).join('')||'<p class="muted">No course assignments in this scope yet.</p>'}</div></div>`;}
function auditRows(list){return list.map(a=>`<div class="audit-row"><i class="audit-dot"></i><div><b>${esc(a.action)}</b><p>${esc(a.detail)}</p><time>${date(a.time)} IST · ${esc(a.actor)}</time></div></div>`).join('')||'<div class="empty">No activity yet.</div>';}
function vActivity(){return head('Activity log','Track account creation, access changes and publishing actions.',`<button class="btn" data-action="export-audit">Export log</button>`)+`<section class="panel">${auditRows(db.audit.filter(a=>!a.org||inScope(a.org)))}</section>`;}
function vSettings(){return head('Workspace settings','Review the preview’s storage and enrollment rules.')+`<div class="split"><section class="panel"><div class="panel-head"><h2>Enrollment policy</h2><span class="pill green">Admin managed</span></div><div class="panel-body"><h3 class="subheading">Students start without access</h3><p class="muted">New students receive no courses, modules or practices unless an admin assigns them. Suspended accounts and archived organizations have no effective access.</p><h3 class="subheading">Organization isolation</h3><p class="muted">A profile belongs to one organization. Its students cannot inherit a profile from another organization.</p><h3 class="subheading">Individual assignments</h3><p class="muted">Individual access replaces the profile, allowing exact module-level selection. You can return a student to their assigned profile at any time.</p><h3 class="subheading">Separate organization portal</h3><p class="muted">Organization members sign in to a dedicated analytics HTML. Their organization is assigned by Platform Admin, with no management pages or organization switcher.</p></div></section><aside class="panel"><div class="panel-head"><h2>Local prototype data</h2></div><div class="panel-body"><p class="muted">This HTML stores its sample workspace in your browser. It supports any number of records within browser storage limits; a production database is needed for large rosters and multiple admins.</p><button class="btn" data-action="backup">Download workspace backup</button><div class="note">Host both student and admin pages on the same origin for shared preview data. Browsers handle local file storage differently.</div><a class="btn" href="otp-slate.html" target="_blank" rel="noopener">Open student portal ↗</a></div></aside></div>`;}

function modal(title,body,submit=null,large=false){
 lastFocus=document.activeElement;$('#root').inert=true;
 $('#dialogs').innerHTML=`<div class="modal-backdrop"><div class="modal${large?' large':''}" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><div class="modal-head"><h2 id="modalTitle">${title}</h2><button data-action="modal-close" aria-label="Close dialog">×</button></div><form id="modalForm"><div class="modal-body">${body}<p id="formError" role="alert" class="error"></p></div><div class="modal-footer"><button type="button" class="btn" data-action="modal-close">${submit?'Cancel':'Close'}</button>${submit?'<button class="btn pri" type="submit">Save changes</button>':''}</div></form></div></div>`;
 const form=$('#modalForm');if(submit)form.addEventListener('submit',async e=>{e.preventDefault();const save=$('button[type=submit]',form);if(save.disabled)return;save.disabled=true;form.dataset.saving='true';const closers=$$('[data-action="modal-close"]',$('.modal'));closers.forEach(b=>b.disabled=true);try{await submit(new FormData(form),form);closeModal();render();toast('Changes saved.');}catch(err){if($('#formError'))$('#formError').textContent=err.message;save.disabled=false;delete form.dataset.saving;closers.forEach(b=>b.disabled=false);}});else form.addEventListener('submit',e=>e.preventDefault());
 const focusable=$('input,select,textarea,button',$('.modal-body'))||$('[data-action="modal-close"]');focusable?.focus();
}
function closeModal(){const open=$('#dialogs').children.length;$('#dialogs').innerHTML='';$('#root').inert=false;if(open)lastFocus?.focus?.();}
function field(label,name,value='',type='text',required=true,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`;}
function selectField(label,name,options,value){return `<label class="field">${label}<select name="${name}">${options.map(([v,n])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(n)}</option>`).join('')}</select></label>`;}
function orgForm(id){guard('orgs');const o=id?db.orgs.find(o=>o.id===id):{name:'',code:'',type:'Organization',city:'',contact:''};modal(id?'Edit organization':'Create organization',`<div class="form-grid">${field('Organization name','name',o.name,'text',true,'maxlength="120"')}${field('Unique organization code','code',o.code,'text',true,'maxlength="16" pattern="[A-Za-z0-9_-]+"')}${selectField('Organization type','type',['Organization','College','Training organization','Company'].map(s=>[s,s]),o.type)}${field('City','city',o.city,'text',false)}${field('Contact email','contact',o.contact,'email')}</div><div class="note">An organization starts with an empty student roster. Students receive access only through assignments made by an admin.</div>`,f=>{guard('orgs');const name=f.get('name').trim(),code=f.get('code').trim().toUpperCase();if(!name)throw new Error('Organization name is required.');if(db.orgs.some(x=>x.id!==id&&x.code.toUpperCase()===code))throw new Error('That organization code already exists.');const data={name,code,type:f.get('type'),city:f.get('city').trim(),contact:f.get('contact').trim()};if(id)Object.assign(o,data);else{const n={id:M.uid(),...data,status:'Active'};db.orgs.push(n);state.org=n.id;}commit(id?'Organization updated':'Organization created',name,id||state.org);});}
function studentForm(id){const s=id?db.students.find(s=>s.id===id&&inScope(s.org)):null;const o=s?db.orgs.find(o=>o.id===s.org):requireOrg('students');guard('students',o.id);if(id&&!s)throw new Error('Student not found in this scope.');const x=s||{student_id:'',name:'',email:'',phone:'',cohort:'',profile:'',status:'Active',accessUntil:''};modal(s?'Edit student':'Add student',`<p class="muted">${esc(o.name)}</p><div class="form-grid">${field('Student ID','student_id',x.student_id)}${field('Full name','full_name',x.name)}${field('Email','email',x.email,'email')}${field('Mobile number','phone',x.phone,'tel',true,'pattern="[6-9][0-9]{9}" maxlength="10"')}${field('Cohort / batch','cohort',x.cohort,'text',false)}${selectField('Account status','status',['Active','Suspended'].map(s=>[s,s]),x.status)}${selectField('Access profile','profile',[['','None — no learning access'],...db.profiles.filter(p=>p.org===o.id).map(p=>[p.id,p.name])],x.profile)}${field('Access expires on (optional)','accessUntil',x.accessUntil,'date',false)}</div>${x.custom?'<p class="note">This student uses individual access. Changing their profile here keeps the individual override. Use View access to return to profile-based access.</p>':'<p class="note">Only the selected access profile is assigned. No courses are automatically enrolled.</p>'}`,f=>{guard('students',o.id);const raw=Object.fromEntries(f);raw.role='Student';raw.access_profile=raw.profile?db.profiles.find(p=>p.id===raw.profile&&p.org===o.id)?.name:'None';const temp={...db,students:db.students.filter(t=>t.id!==id)};const [r]=M.validateRows(temp,o.id,[raw]);if(r.errors.length)throw new Error(r.errors.join('. '));if(raw.profile&&!db.profiles.some(p=>p.id===raw.profile&&p.org===o.id))throw new Error('Profile is outside this organization.');r.data.accessUntil=raw.accessUntil;if(s)Object.assign(s,r.data,{id:s.id,custom:s.custom,created:s.created});else db.students.push(r.data);commit(s?'Student updated':'Student created',r.data.name,o.id);});}
function profileForm(id){const p=id?db.profiles.find(p=>p.id===id&&inScope(p.org)):null;const o=p?db.orgs.find(o=>o.id===p.org):requireOrg('access');guard('access',o.id);modal(p?'Edit access profile':'Create access profile',`<p class="muted">${esc(o.name)}</p>${field('Profile name','name',p?.name||'')}${field('Description','description',p?.description||'','text',false)}${grantEditor(p?.grants)}`, (f,form)=>{guard('access',o.id);const name=f.get('name').trim();if(!name)throw new Error('Profile name is required.');if(db.profiles.some(x=>x.id!==id&&x.org===o.id&&x.name.toLowerCase()===name.toLowerCase()))throw new Error('This profile name already exists.');const data={name,description:f.get('description').trim(),grants:readGrants(form)};if(p)Object.assign(p,data);else{const n={id:M.uid(),org:o.id,...data};db.profiles.push(n);state.profile=n.id;}commit(p?'Access profile updated':'Access profile created',name+' · '+grantSummary(data.grants),o.id);},true);}
function viewStudent(id){const s=db.students.find(s=>s.id===id&&inScope(s.org));if(!s)throw new Error('Student not found.');const g=M.effective(db,s);modal('Student access',`<div class="preview-person"><div class="avatar">${esc(s.name.split(' ').map(n=>n[0]).slice(0,2).join(''))}</div><div><b>${esc(s.name)}</b><p class="muted">${esc(s.student_id)} · ${esc(orgName(s.org))}<br>${esc(profileName(s))}</p></div></div><div class="checks">${badge(s.status)}<span class="pill">${grantSummary(g)}</span></div><div class="actions" style="margin:20px 0"><button type="button" class="btn pri" data-action="individual-access" data-id="${s.id}"${disabled('access')}>Edit individual access</button><button type="button" class="btn" data-action="restore-profile" data-id="${s.id}" ${s.custom&&can('access')?'':'disabled'}>Use assigned profile</button><a class="btn" href="otp-slate.html?student=${encodeURIComponent(s.id)}" target="_blank" rel="noopener">Preview student portal ↗</a></div>${grantList(g)}`,null,true);}
function individualForm(id){const s=db.students.find(s=>s.id===id&&inScope(s.org));guard('access',s?.org);if(!s)throw new Error('Student not found.');const g=s.custom||db.profiles.find(p=>p.id===s.profile&&p.org===s.org)?.grants||M.emptyGrants();modal('Individual access · '+esc(s.name),`<div class="note">These selections replace the student’s profile. Choose exactly which modules and practices this student can use.</div>${grantEditor(g)}`,(f,form)=>{guard('access',s.org);s.custom=readGrants(form);commit('Individual access updated',s.name+' · '+grantSummary(s.custom),s.org);},true);}
function selectedStudents(){return db.students.filter(s=>state.selected.has(s.id)&&inScope(s.org));}
function bulkProfile(){guard('access');const selected=selectedStudents();if(!selected.length)throw new Error('Select students first.');const ids=[...new Set(selected.map(s=>s.org))];if(ids.length!==1)throw new Error('Assign a profile to students from one organization at a time.');const org=ids[0];modal('Assign learning access',`<p>Assign a profile to <b>${selected.length}</b> selected students.</p>${selectField('Access profile','profile',[['','None — revoke learning access'],...db.profiles.filter(p=>p.org===org).map(p=>[p.id,p.name])],'')}<div class="note">This replaces individual overrides. Suspended accounts remain suspended.</div>`,f=>{guard('access',org);const profile=f.get('profile');if(profile&&!db.profiles.some(p=>p.id===profile&&p.org===org))throw new Error('Profile is outside this organization.');selected.forEach(s=>{s.profile=profile;s.custom=null;});commit('Bulk access assigned',selected.length+' students · '+(db.profiles.find(p=>p.id===profile)?.name||'No access'),org);state.selected.clear();});}
function cohortProfile(){const o=requireOrg('access'),cohorts=[...new Set(db.students.filter(s=>s.org===o.id).map(s=>s.cohort).filter(Boolean))];if(!cohorts.length)throw new Error('Add students with a cohort name first.');modal('Assign access to a cohort',`<p class="muted">${esc(o.name)}</p>${selectField('Cohort','cohort',cohorts.map(c=>[c,c]),cohorts[0])}${selectField('Access profile','profile',[['','None — revoke learning access'],...db.profiles.filter(p=>p.org===o.id).map(p=>[p.id,p.name])],'')}<div class="note">Applies to every current student in the selected cohort, across all roster pages. Individual overrides are replaced. New students added later must be assigned through import or by an admin.</div>`,f=>{guard('access',o.id);const p=f.get('profile');if(p&&!db.profiles.some(x=>x.id===p&&x.org===o.id))throw new Error('Invalid access profile.');const cohort=f.get('cohort'),members=db.students.filter(s=>s.org===o.id&&s.cohort===cohort);if(!members.length)throw new Error('This cohort has no students.');members.forEach(s=>{s.profile=p;s.custom=null;});commit('Cohort access assigned',cohort+' · '+members.length+' students',o.id);});}
function confirmAction(title,message,button,fn){modal(title,`<p>${message}</p>`,()=>fn());$('#modalForm button[type=submit]').textContent=button;}
function examForm(id){const e=id?db.exams.find(e=>e.id===id&&inScope(e.org)):null;const o=e?db.orgs.find(o=>o.id===e.org):requireOrg('exams');guard('exams',o.id);if(e?.status==='Published')throw new Error('Withdraw the exam before editing it.');const cohorts=[...new Set(db.students.filter(s=>s.org===o.id).map(s=>s.cohort).filter(Boolean))];modal(e?'Edit exam':'Create exam draft',`<p class="muted">${esc(o.name)}</p>${field('Exam title','title',e?.title||'')}<div class="form-grid">${selectField('Question set','kind',[['aptitude','Aptitude · 5 sample questions'],['coding','Coding · Two Sum sample problem']],e?.kind||'aptitude')}${field('Duration (minutes)','duration',e?.duration||10,'number',true,'min="1" max="180"')}${selectField('Audience','cohort',[['','All active students'],...cohorts.map(c=>[c,c])],e?.cohort||'')}${field('Closing time (optional, IST)','deadline',e?.deadline?new Date(new Date(e.deadline).getTime()+330*60000).toISOString().slice(0,16):'','datetime-local',false)}</div><div class="note">Save a draft first. Publishing explicitly grants the selected audience access to this exam. Drafts are never shown in the student portal.</div>`,f=>{guard('exams',o.id);const duration=+f.get('duration');if(!Number.isInteger(duration)||duration<1||duration>180)throw new Error('Duration must be 1–180 minutes.');const close=f.get('deadline')?new Date(f.get('deadline')+':00+05:30').toISOString():'';const data={title:f.get('title').trim(),kind:f.get('kind'),duration,cohort:f.get('cohort'),deadline:close,status:e?.status||'Draft'};if(!data.title)throw new Error('Exam title is required.');if(e)Object.assign(e,data);else db.exams.push({id:M.uid(),org:o.id,...data});commit(e?'Exam draft updated':'Exam draft created',data.title,o.id);});}
function jobForm(id){const j=id?db.jobs.find(j=>j.id===id&&inScope(j.org)):null;const o=j?db.orgs.find(o=>o.id===j.org):requireOrg('jobs');guard('jobs',o.id);modal(j?'Edit job posting':'Add job posting',`<p class="muted">${esc(o.name)}</p><div class="form-grid">${field('Job title','title',j?.title||'')}${field('Company','company',j?.company||'')}${field('Location','location',j?.location||'','text',false)}${field('Posting date','posted',j?.posted||'2026-10-06','date')}</div>${field('Original application URL','url',j?.url||'','url')}<label class="field">Job description<textarea name="description" rows="5" required>${esc(j?.description||'')}</textarea></label>`,f=>{guard('jobs',o.id);const data=Object.fromEntries(f);const url=new URL(data.url);if(!['https:','http:'].includes(url.protocol))throw new Error('Use a valid HTTP or HTTPS application link.');for(const k of ['title','company','description'])if(!data[k].trim())throw new Error('Complete the required fields.');if(j)Object.assign(j,data);else db.jobs.push({id:M.uid(),org:o.id,status:'Draft',...data});commit(j?'Job updated':'Job draft created',data.title,o.id);});}
function staffForm(id){
 const member=id?db.members.find(s=>s.id===id&&inScope(s.org)):null;
 const o=member?db.orgs.find(o=>o.id===member.org):requireOrg('staff');if(id&&!member)throw new Error('Member not found.');
 modal(member?'Edit organization member':'Create organization member',`<p class="muted">${esc(o.name)} · Read-only analytics access</p>${field('Full name','name',member?.name||'','text',true,'maxlength="120"')}${field('Member email / login ID','email',member?.email||'','email')}${field(member?.credential?'New password (leave blank to keep current)':'Assign password','password','','password',!member?.credential,'minlength="10" maxlength="128" autocomplete="new-password"')}${field('Confirm password','confirm','','password',!member?.credential,'maxlength="128" autocomplete="new-password"')}<div class="note">Share the assigned login details with this member separately. Passwords are stored as salted hashes in this local prototype. No invitation email is sent.</div>`,async f=>{
  const name=f.get('name').trim(),email=f.get('email').trim().toLowerCase(),password=f.get('password'),confirmation=f.get('confirm');
  if(!name||name.length>120)throw new Error('Enter a full name (max 120 characters).');
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Enter a valid email.');
  if(db.members.some(s=>s.id!==id&&s.email.toLowerCase()===email))throw new Error('This email already has a member account.');
  if(password!==confirmation)throw new Error('Passwords do not match.');
  if(!member?.credential&&!password)throw new Error('Assign a password for this member.');
  const credential=password?await M.createCredential(password):member.credential;
  // Refresh after hashing to avoid overwriting changes from another tab.
  db=M.load();if(db.members.some(s=>s.id!==id&&s.email.toLowerCase()===email))throw new Error('This email already has a member account.');
  if(db.orgs.find(x=>x.id===o.id)?.status!=='Active')throw new Error('Restore this organization first.');
  if(member){const target=db.members.find(s=>s.id===id);if(!target)throw new Error('Member no longer exists.');Object.assign(target,{name,email,credential,credentialVersion:(target.credentialVersion||1)+(password||email!==target.email?1:0)});}
  else db.members.push({id:M.uid(),org:o.id,name,email,credential,credentialVersion:1,status:'Active',created:new Date().toISOString().slice(0,10)});
  commit(member?'Organization member updated':'Organization member created',name+' · '+email,o.id);
 });
}
function download(name,content,type='text/csv;charset=utf-8'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
function exportStudents(){const list=filteredStudents();download('student-access-report.csv',csv([['organization','student_id','full_name','email','phone','role','cohort','status','profile','courses','practices','access_expires'],...list.map(s=>{const g=M.effective(db,s);return [orgName(s.org),s.student_id,s.name,s.email,s.phone,s.role,s.cohort,s.status,profileName(s),Object.keys(g.courses).join(';'),g.practices.join(';'),s.accessUntil];})]));}
function loadImport(rows,name){const org=requireOrg('students');if(!rows.length)throw new Error('No student rows found.');state.import={name,org:org.id,raw:rows,rows:M.validateRows(db,org.id,rows)};render();}
async function importFile(file){
 requireOrg('students');if(!file)return;if(file.size>10*1024*1024)throw new Error('File exceeds 10 MB. Split your roster into smaller files.');if(!/\.(xlsx|csv)$/i.test(file.name))throw new Error('Choose an .xlsx or .csv file.');
 const buffer=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('The file could not be read.'));reader.readAsArrayBuffer(file);});
 const book=XLSX.read(buffer,{type:'array',cellFormula:true});const sheet=book.Sheets.Students||book.Sheets[book.SheetNames[0]];if(!sheet)throw new Error('No worksheet found.');
 if(Object.entries(sheet).some(([k,c])=>!k.startsWith('!')&&c.f))throw new Error('The roster must contain values, not formulas. Paste as values and upload again.');
 const matrix=XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:false,blankrows:false});const headers=(matrix[0]||[]).map(v=>String(v).trim().toLowerCase());
 for(const h of ['student_id','full_name','email','phone','role','status'])if(!headers.includes(h))throw new Error('Missing required column: '+h);
 if(new Set(headers.filter(Boolean)).size!==headers.filter(Boolean).length)throw new Error('The sheet contains duplicate headers.');
 const rows=matrix.slice(1).filter(row=>row.some(v=>String(v).trim())).map(row=>Object.fromEntries(headers.map((h,i)=>[h,row[i]??''])));loadImport(rows,file.name);
}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action]');if(!button||button.disabled)return;
 const {action,id,view}=button.dataset;
 try{
  if(action==='login'){state.org='all';signedIn=true;try{sessionStorage.setItem('otp-slate-admin-session','active');}catch(_){}render();return;}
  if(!signedIn)return;
  switch(action){
   case 'nav':nav(view);break;
   case 'logout':signedIn=false;try{sessionStorage.removeItem('otp-slate-admin-session');}catch(_){}closeModal();render();break;
   case 'modal-close':closeModal();break;
   case 'new-org':orgForm();break;case 'edit-org':orgForm(id);break;
   case 'open-org':if(!allowedOrgs().some(o=>o.id===id))throw new Error('Organization is outside your scope.');state.org=id;nav('students');break;
   case 'org-status':{guard('orgs');const o=db.orgs.find(o=>o.id===id);confirmAction(o.status==='Active'?'Archive organization':'Restore organization',o.status==='Active'?'Archiving disables effective access for all students in this organization. Records are preserved.':'Restoring re-enables access for active students based on their existing assignments.',o.status==='Active'?'Archive':'Restore',()=>{guard('orgs');o.status=o.status==='Active'?'Archived':'Active';commit('Organization '+o.status.toLowerCase(),o.name,o.id);});break;}
   case 'new-student':studentForm();break;case 'edit-student':studentForm(id);break;case 'student-view':viewStudent(id);break;
   case 'individual-access':individualForm(id);break;
   case 'restore-profile':{const s=db.students.find(s=>s.id===id&&inScope(s.org));guard('access',s?.org);s.custom=null;commit('Profile access restored',s.name,s.org);closeModal();render();toast('Assigned profile restored.');break;}
   case 'bulk-profile':bulkProfile();break;
   case 'assign-cohort':cohortProfile();break;
   case 'bulk-status':{guard('students');const list=selectedStudents();if(!list.length)throw new Error('Select students first.');const status=button.dataset.status;confirmAction(status==='Active'?'Activate students':'Suspend students',`Set ${list.length} selected student accounts to ${status.toLowerCase()}?`,status==='Active'?'Activate':'Suspend',()=>{list.forEach(s=>{guard('students',s.org);s.status=status;});for(const org of new Set(list.map(s=>s.org)))commit('Bulk status updated',list.filter(s=>s.org===org).length+' students · '+status,org);state.selected.clear();});break;}
   case 'page':state.page=Math.max(0,state.page+Number(button.dataset.dir));$('#studentTable').innerHTML=studentTable();break;
   case 'new-profile':profileForm();break;case 'edit-profile':profileForm(id);break;
   case 'profile-select':state.profile=id;render();break;
   case 'profile-students':{const p=db.profiles.find(p=>p.id===id&&inScope(p.org));state.org=p.org;nav('students');state.query='';state.selected=new Set(db.students.filter(s=>s.org===p.org&&s.profile===p.id&&!s.custom).map(s=>s.id));render();break;}
   case 'template':{const bytes=Uint8Array.from(atob(STUDENT_TEMPLATE_BASE64),c=>c.charCodeAt(0));download('student-import-template.xlsx',bytes,'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');break;}
   case 'demo-import':loadImport([{student_id:'DEMO101',full_name:'Example Learner',email:'learner101@example.com',phone:'9000100101',role:'Student',cohort:'Batch 2027',access_profile:'None',status:'Active'},{student_id:'DEMO102',full_name:'Sample Student',email:'learner102@example.com',phone:'9000100102',role:'Student',cohort:'Batch 2027',access_profile:'None',status:'Active'}],'Sample roster');break;
   case 'cancel-import':state.import=null;render();break;
   case 'commit-import':{const o=requireOrg('students'),i=state.import;if(!i||i.org!==o.id)throw new Error('Organization scope changed. Upload the file again.');const rows=M.validateRows(db,o.id,i.raw);if(rows.some(r=>r.errors.length))throw new Error('The import contains errors. Revalidate the file.');db.students.push(...rows.map(r=>r.data));commit('Students imported',rows.length+' students from '+i.name,o.id);state.import=null;nav('students');toast(rows.length+' students created.');break;}
   case 'export-import-errors':download('student-import-errors.csv',csv([['row','student_id','email','errors'],...state.import.rows.filter(r=>r.errors.length).map(r=>[r.row,r.data.student_id,r.data.email,r.errors.join('; ')])]));break;
   case 'new-exam':examForm();break;case 'edit-exam':examForm(id);break;
   case 'exam-publish':{const x=db.exams.find(x=>x.id===id&&inScope(x.org));guard('exams',x?.org);if(db.orgs.find(o=>o.id===x.org)?.status!=='Active')throw new Error('Restore this organization first.');const publish=x.status!=='Published';if(publish&&x.deadline&&new Date(x.deadline)<=new Date())throw new Error('The closing time has passed. Update the draft before publishing.');confirmAction(publish?'Publish exam':'Withdraw exam',publish?`Release ${esc(x.title)} to ${examAudience(x).length} active students?`:'Remove this exam from the student portal?',publish?'Publish':'Withdraw',()=>{guard('exams',x.org);x.status=publish?'Published':'Withdrawn';commit('Exam '+x.status.toLowerCase(),x.title,x.org);});break;}
   case 'exam-audience':{const x=db.exams.find(x=>x.id===id&&inScope(x.org));modal('Exam audience',`<p class="muted">${esc(x.title)} · ${examAudience(x).length} active students</p><ul>${examAudience(x).map(s=>`<li>${esc(s.name)} · ${esc(s.student_id)}</li>`).join('')}</ul>`);break;}
   case 'new-job':jobForm();break;case 'edit-job':jobForm(id);break;
   case 'job-publish':{const j=db.jobs.find(j=>j.id===id&&inScope(j.org));guard('jobs',j?.org);j.status=j.status==='Published'?'Draft':'Published';commit('Job '+(j.status==='Published'?'published':'unpublished'),j.title,j.org);render();toast('Posting updated.');break;}
   case 'new-staff':staffForm();break;case 'edit-staff':staffForm(id);break;
   case 'member-status':{const member=db.members.find(s=>s.id===id&&inScope(s.org));if(!member)throw new Error('Member not found.');const active=member.status==='Active';if(!active&&!member.credential)throw new Error('Assign a password before activating this member.');confirmAction(active?'Disable member':'Activate member',active?'This member will lose access to the organization analytics portal.':'Restore this member’s analytics access.',active?'Disable':'Activate',()=>{member.status=active?'Disabled':'Active';member.credentialVersion=(member.credentialVersion||1)+1;commit('Organization member '+member.status.toLowerCase(),member.email,member.org);});break;}
   case 'export-students':exportStudents();break;
   case 'export-audit':download('admin-activity.csv',csv([['time','actor','organization','action','details'],...db.audit.filter(a=>!a.org||inScope(a.org)).map(a=>[a.time,a.actor,a.org?orgName(a.org):'Workspace',a.action,a.detail])]));break;
   case 'backup':{const allowed=allowedOrgs().map(o=>o.id);const scoped={...db,orgs:orgs(),students:students(),profiles:db.profiles.filter(p=>inScope(p.org)),exams:db.exams.filter(x=>inScope(x.org)),jobs:db.jobs.filter(j=>inScope(j.org)),members:db.members.filter(s=>inScope(s.org)),audit:db.audit.filter(a=>!a.org||inScope(a.org))};download('slate-workspace-backup.json',JSON.stringify(scoped,null,2),'application/json');break;}
  }
 }catch(err){toast(err.message);}
});
document.addEventListener('change',e=>{
 try{
  if(e.target.id==='orgSelect'){state.org=e.target.value;state.query='';state.selected.clear();state.page=0;state.import=null;render();}
  else if(e.target.id==='studentStatus'){state.status=e.target.value;state.page=0;$('#studentTable').innerHTML=studentTable();}
  else if(e.target.dataset.select){if(e.target.checked)state.selected.add(e.target.dataset.select);else state.selected.delete(e.target.dataset.select);$('#selectedCount').textContent=state.selected.size+' selected';}
  else if(e.target.id==='selectPage'){for(const s of filteredStudents().slice(state.page*20,(state.page+1)*20))if(e.target.checked)state.selected.add(s.id);else state.selected.delete(s.id);$('#studentTable').innerHTML=studentTable();$('#selectedCount').textContent=state.selected.size+' selected';}
  else if(e.target.dataset.courseAll){const id=e.target.dataset.courseAll;$$(`[data-module="${id}"]`,$('#modalForm')).forEach(x=>x.checked=e.target.checked);}
  else if(e.target.dataset.module){const id=e.target.dataset.module;$(`[data-course-all="${id}"]`,$('#modalForm')).checked=$$(`[data-module="${id}"]`,$('#modalForm')).every(x=>x.checked);}
  else if(e.target.id==='importFile'){toast('Reading and validating file…');importFile(e.target.files[0]).catch(err=>toast(err.message));}
 }catch(err){toast(err.message);}
});
document.addEventListener('input',e=>{if(e.target.id==='studentSearch'){state.query=e.target.value;state.page=0;$('#studentTable').innerHTML=studentTable();}});
document.addEventListener('keydown',e=>{
 const d=$('.modal');if(!d)return;if(e.key==='Escape'&&$('#modalForm')?.dataset.saving)return;if(e.key==='Escape'){closeModal();return;}
 if(e.key==='Tab'){const nodes=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]',d);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
});
window.addEventListener('storage',e=>{if(e.key===M.KEY){try{db=M.load();state.import=null;render();toast('Workspace refreshed from another tab.');}catch(_){toast('Could not load changes from the other tab.');}}});
render();
